import {
  PAGE_STYLE_TYPES,
  type AlbumConfig,
  type PageConfig,
  type PageStyleType,
} from "../types";

/**
 * The decorative treatment a greeting page should wear.
 *
 * A page may name its own style, and that wins outright — an album-wide choice
 * is a default, not a rule, so one greeting can be dressed differently without
 * disturbing the rest. Failing that, syncing borrows the cover's style so the
 * whole album reads as one object. The cover has one style pages cannot wear —
 * a full-bleed hero photo, which a page has nothing to fill itself with — so
 * that case lands on the plain treatment and the album's own backdrop carries
 * the look instead.
 */
export function resolvePageStyle(
  album: AlbumConfig,
  page?: PageConfig | null,
): PageStyleType {
  if (isPageStyle(page?.pageStyle)) return page.pageStyle;
  const chosen = album.syncPageStyleWithCover ? album.coverStyle : album.pageStyle;
  return isPageStyle(chosen) ? chosen : "MINIMAL";
}

/**
 * The style classes a page surface wears. `custom-bg` suppresses the styles
 * that paint a material — aged paper, foil — because a page that was given its
 * own backdrop asked for that backdrop to be seen; its frame still draws.
 */
export function pageStyleClass(
  album: AlbumConfig,
  hasOwnBackground: boolean,
  page?: PageConfig | null,
) {
  const slug = resolvePageStyle(album, page).toLowerCase().replace(/_/g, "-");
  return `ae-page--style-${slug}${hasOwnBackground ? " ae-page--custom-bg" : ""}`;
}

function isPageStyle(value: unknown): value is PageStyleType {
  return PAGE_STYLE_TYPES.includes(value as PageStyleType);
}
